using KitWright.Editor.Tools.Scripting;
using UnityEngine;
using UnityEngine.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using TMPro;
using System.Text;

public class CommandScript : IKitWrightCommand
{
    public void Execute(ExecutionContext ctx)
    {
        var sb = new StringBuilder();
        var scene = EditorSceneManager.GetActiveScene();
        if (!scene.path.Contains("LoginMenu"))
            scene = EditorSceneManager.OpenScene("Assets/Project/LoginMenu.unity");

        var logo = AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Project/Resources/UI/YellowHUD/Logo_Railbound_Yellow.png");
        var loginUi = Object.FindObjectOfType<LoginUI>(true);
        sb.AppendLine("loginUi=" + (loginUi != null) + " title=" + (loginUi != null && loginUi.gameTitle != null) + " logoSprite=" + (logo != null));

        Transform brandParent = null;
        if (loginUi != null && loginUi.gameTitle != null)
            brandParent = loginUi.gameTitle.transform.parent;
        if (brandParent == null)
        {
            var canvas = GameObject.Find("Canvas");
            brandParent = canvas != null ? canvas.transform : null;
        }

        // Prefer LoginDock as brand parent
        var dock = GameObject.Find("LoginDock");
        if (dock != null) brandParent = dock.transform;

        if (brandParent != null && logo != null && brandParent.Find("Logo_Railbound_Yellow") == null)
        {
            var go = new GameObject("Logo_Railbound_Yellow", typeof(RectTransform), typeof(CanvasRenderer), typeof(Image));
            ctx.RegisterObjectCreation(go);
            go.transform.SetParent(brandParent, false);
            go.transform.SetAsFirstSibling();
            var rt = go.GetComponent<RectTransform>();
            rt.anchorMin = new Vector2(0f, 1f);
            rt.anchorMax = new Vector2(0f, 1f);
            rt.pivot = new Vector2(0f, 1f);
            rt.sizeDelta = new Vector2(280f, 72f);
            rt.anchoredPosition = new Vector2(24f, -18f);
            var img = go.GetComponent<Image>();
            img.sprite = logo;
            img.preserveAspect = true;
            img.raycastTarget = false;
            sb.AppendLine("logo created under " + brandParent.name);
        }
        else sb.AppendLine("logo skip parent=" + (brandParent != null ? brandParent.name : "null"));

        // Instantiate Reach Modal Window prefab as optional visual shell reference (keep existing AccountLoginPopup functional)
        var modalPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Reach - Complete Sci-Fi UI/Prefabs/UI Elements/Modal Window/Modal Window.prefab");
        sb.AppendLine("modalPrefab=" + (modalPrefab != null));

        // Apply Reach ButtonManager-like solid yellow on Guest via Button colors
        if (loginUi != null && loginUi.registerButton != null)
        {
            var colors = loginUi.registerButton.colors;
            colors.normalColor = Color.white;
            colors.highlightedColor = new Color(1f, 0.94f, 0.55f, 1f);
            colors.pressedColor = new Color(0.85f, 0.7f, 0f, 1f);
            colors.selectedColor = Color.white;
            loginUi.registerButton.colors = colors;
            ctx.RegisterObjectModification(loginUi.registerButton);
        }

        // Ensure AccountLoginPopup / CreateAccountPopup use dark steel + yellow titles
        Color yellow = new Color(1f, 0.816f, 0f, 1f);
        foreach (var name in new[] { "AccountLoginPopup", "CreateAccountPopup", "ErrorPopup" })
        {
            var go = GameObject.Find("Canvas/" + name);
            if (go == null) continue;
            foreach (var tmp in go.GetComponentsInChildren<TMP_Text>(true))
            {
                if (tmp.name.Contains("Title") || tmp.name.Contains("PopupTitle"))
                {
                    ctx.RegisterObjectModification(tmp);
                    tmp.color = yellow;
                    if (tmp.name.Contains("PopupTitle") || tmp.name == "ErrorTitle")
                        tmp.fontStyle = FontStyles.Bold;
                }
            }
        }

        // Add hover to age/terms if missing
        if (loginUi != null)
        {
            void Hover(Button b)
            {
                if (b == null) return;
                if (b.GetComponent<Railbound.UI.TacticalUIHoverEffect>() == null)
                {
                    var h = b.gameObject.AddComponent<Railbound.UI.TacticalUIHoverEffect>();
                    ctx.RegisterObjectCreation(h);
                }
            }
            Hover(loginUi.ageCheckboxButton);
            Hover(loginUi.termsCheckboxButton);
            Hover(loginUi.forgotPasswordButton);
            Hover(loginUi.closeAccountLoginButton);
            Hover(loginUi.closeCreateAccountButton);
            Hover(loginUi.openCreateAccountButton);
        }

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        sb.AppendLine("saved");
        ctx.ReturnValue = sb.ToString();
    }
}
